        return [grid[:,c:c+5] for c in range(0,W,6)]
    if W==5:
        return [grid[r:r+5,:] for r in range(0,H,6)]
    # square grid 11x11
    return [grid[r:r+5,c:c+5] for r in (0,6) for c in (0,6)]
